import csv, pathlib
src=pathlib.Path('measurements/transport-isotropy-diagnostic-v1-compact-run-002'); out=pathlib.Path('measurements/transport-isotropy-cycle-audit-v1'); out.mkdir(exist_ok=True)
cases=[('R01_1_0_0',1,0,0,286,166,166),('R08_1_1_0',1,1,0,226,226,166),('R09_1_1_1',1,1,1,206,206,206)]
def load(d):
    with (src/d/'update-trace.csv').open() as f:return list(csv.DictReader(f))
def write(name,fields,rows):
    with (out/name).open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
def n(r,k):return float(r[k])
timing=[];transitions=[];final=[];pressure=[];direct=[];safety=[]
for name,dx,dy,dz,rx,ry,rz in cases:
    rows=load(name);completed=[r for r in rows if r['cycleCompleted']=='true'];previous=''
    for number,row in enumerate(completed,1):
        u=int(row['update']);timing.append({'directionId':name,'directionX':dx,'directionY':dy,'directionZ':dz,'receiverCycleNumber':number,'completionUpdate':u,'previousCompletionUpdate':previous,'cycleDurationUpdates':u-int(previous) if previous else '','samplesPerCycle':'not persisted','sourceCycleAtCompletion':row['sourceCycle'],'note':''});previous=str(u)
    if not completed:
        timing.append({'directionId':name,'directionX':dx,'directionY':dy,'directionZ':dz,'receiverCycleNumber':0,'completionUpdate':'','previousCompletionUpdate':'','cycleDurationUpdates':'','samplesPerCycle':'','sourceCycleAtCompletion':'','note':'NO_RECEIVER_CYCLE_COMPLETED'})
        transitions.append({'directionId':name,'update':'','sourceCycle':rows[-1]['sourceCycle'],'receiverCycleBefore':0,'receiverCycleAfter':0,'cycleCompleted':'false','velocityZPrevious':'','velocityZCurrent':'','note':'NO_TRANSITION_RECORDED; receiver velocity was not persisted'})
    last=rows[-1];p198=rows[197];firstp=next((r['update'] for r in rows if any(n(r,'pressureAfter'+a)!=0 for a in 'XYZ')),'');firstg=next((r['update'] for r in rows if any(n(r,'rawGradient'+a)!=0 for a in 'XYZ')),'')
    final.append({'directionId':name,'update':last['update'],'rawGradientX':last['rawGradientX'],'rawGradientY':last['rawGradientY'],'rawGradientZ':last['rawGradientZ'],'scaledGradientX':last['scaledGradientX'],'scaledGradientY':last['scaledGradientY'],'scaledGradientZ':last['scaledGradientZ'],'cycleGradientImbalanceX':last['cycleGradientImbalanceX'],'cycleGradientImbalanceY':last['cycleGradientImbalanceY'],'cycleGradientImbalanceZ':last['cycleGradientImbalanceZ'],'accelerationX':last['accelerationX'],'accelerationY':last['accelerationY'],'accelerationZ':last['accelerationZ'],'transportMomentumX':last['transportMomentumAfterX'],'transportMomentumY':last['transportMomentumAfterY'],'transportMomentumZ':last['transportMomentumAfterZ'],'pressureX':last['pressureAfterX'],'pressureY':last['pressureAfterY'],'pressureZ':last['pressureAfterZ'],'receiverCycleCount':len(completed),'samplesInCurrentIncompleteCycle':len(rows),'receiverVelocityZ':'not persisted','velocityNote':'not present in source trace'})
    pressure.append({'directionId':name,'firstNonzeroPressureUpdate':firstp,'pressureAtUpdate198X':p198['pressureAfterX'],'pressureAtUpdate198Y':p198['pressureAfterY'],'pressureAtUpdate198Z':p198['pressureAfterZ'],'pressureAtFinalUpdateX':last['pressureAfterX'],'pressureAtFinalUpdateY':last['pressureAfterY'],'pressureAtFinalUpdateZ':last['pressureAfterZ'],'pressureContinuesDuringIncompleteCycle':any(r['pressureAfterX']!=p198['pressureAfterX'] or r['pressureAfterY']!=p198['pressureAfterY'] or r['pressureAfterZ']!=p198['pressureAfterZ'] for r in rows[198:])})
    direct.append({'directionId':name,'sourceToReceiverGraphDistance':120,'firstObservedNonzeroGradientUpdate':firstg,'arrivalCriterion':'exact nonzero recorded value'})
    safety.append({'directionId':name,'receiverCoordinate':f'{rx};{ry};{rz}','nearestRelevantBoundary':f'332;{ry};{rz}','graphDistanceSourceToBoundary':71,'graphDistanceBoundaryToReceiver':332-rx,'minimumReflectionPathLength':71+332-rx,'earliestPossibleContaminatedUpdate':71+332-rx,'maximumReflectionSafeUpdate':70+332-rx,'safetyClassification':'CONSERVATIVE_LOWER_BOUND','basis':'Manhattan graph; occupied source boundary center +/-95; one edge/update lower bound'})
write('receiver-cycle-timing.csv',['directionId','directionX','directionY','directionZ','receiverCycleNumber','completionUpdate','previousCompletionUpdate','cycleDurationUpdates','samplesPerCycle','sourceCycleAtCompletion','note'],timing)
write('receiver-cycle-sign-transitions.csv',['directionId','update','sourceCycle','receiverCycleBefore','receiverCycleAfter','cycleCompleted','velocityZPrevious','velocityZCurrent','note'],transitions)
write('final-receiver-state.csv',list(final[0]),final);write('pressure-history-summary.csv',list(pressure[0]),pressure);write('direct-wave-timing.csv',list(direct[0]),direct);write('reflection-safety.csv',list(safety[0]),safety)
(out/'CONFIGURATION-STATUS.md').write_text('# Configuration Status\n\nStatus: INSUFFICIENT_RECEIVER_CYCLE_INFORMATION\n\nNo receiver cycle completed in the persisted 600-update traces. Receiver velocity was not persisted, so no sign transition is reconstructed. Reflection values are conservative Manhattan lower bounds. No rerun was performed.\n')
(out/'report.md').write_text('# Compact Transport Receiver Cycle-Timing and Reflection-Safety Audit\n\nUsed only persisted compact traces; no rerun or physics change. Receiver completion is the existing Z-velocity transition from positive to negative, then negative to nonnegative. Completion scans history, stores samplesPerCycle, and resets history/extrema. Source period is 18 updates and is not receiver timing.\n\nNo receiver cycle completed for R01, R08, or R09 in 600 updates. Timing trend is INSUFFICIENT_CYCLES_FOR_TIMING_TREND. Receiver velocity was not persisted. Conservative reflected-path lower bounds are 117, 177, and 197 updates respectively, giving common conservative safe limit 116. These are graph lower bounds, not exact arrival times.\n\nDecision: INSUFFICIENT_RECEIVER_CYCLE_INFORMATION; no longer run authorized.\n')
